fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    assert_eq!(
        arr1.len(),
        arr2.len(),
        "Both input arrays must have the same length"
    );

    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(a, b)| a + b)
        .collect()
}

fn main() {
    let a = vec![1, 2, 3, 4];
    let b = vec![10, 20, 30, 40];
    let result = add_list(&a, &b);
    println!("{:?}", result); // [11, 22, 33, 44]
}